std::set<int> unique_sorted_data;

unique_sorted_data.insert(42);
unique_sorted_data.insert(10);
unique_sorted_data.insert(42); // Duplicate ignored

size_t total = unique_sorted_data.size();

// Efficient logarithmic search
bool exists = unique_sorted_data.count(10);

unique_sorted_data.erase(42);

// Iteration yields elements in ascending order (std::less<int> default)
for (int x : unique_sorted_data) {
    // x will be sorted
}

// Custom sort order (Descending)
std::set<int, std::greater<int>> desc_set;
desc_set.insert(100); // Iteration starts from 100
desc_set.insert(50);
